import { useState, useRef, useCallback } from "react";
import { createPortal } from "react-dom";
import { Info } from "lucide-react";
import { motion } from "framer-motion";
import { cn } from "../../lib/utils";

export default function StatsCard({
  title,
  value,
  subtitle,
  icon: Icon,
  trend,
  trendValue,
  gradient,
  className,
  tooltip,
}) {
  const isPositive = trend === "up";
  const isNegative = trend === "down";

  const [tooltipVisible, setTooltipVisible] = useState(false);
  const [tooltipPos, setTooltipPos] = useState({ top: 0, left: 0 });
  const iconRef = useRef(null);

  const TOOLTIP_WIDTH = 224; // w-56

  const handleMouseEnter = useCallback(() => {
    if (iconRef.current) {
      const rect = iconRef.current.getBoundingClientRect();
      const spaceRight = window.innerWidth - rect.right;
      const left = spaceRight >= TOOLTIP_WIDTH + 8
        ? rect.right + 8
        : rect.left - TOOLTIP_WIDTH - 8;
      setTooltipPos({ top: rect.top, left });
      setTooltipVisible(true);
    }
  }, []);

  const handleMouseLeave = useCallback(() => {
    setTooltipVisible(false);
  }, []);

  const gradients = {
    cyan: "from-cyan-500/20 to-cyan-500/5 border-cyan-500/30",
    violet: "from-violet-500/20 to-violet-500/5 border-violet-500/30",
    fuchsia: "from-fuchsia-500/20 to-fuchsia-500/5 border-fuchsia-500/30",
    emerald: "from-emerald-500/20 to-emerald-500/5 border-emerald-500/30",
    amber: "from-amber-500/20 to-amber-500/5 border-amber-500/30",
    rose: "from-rose-500/20 to-rose-500/5 border-rose-500/30",
  };

  const iconColors = {
    cyan: "text-cyan-400 bg-cyan-500/20",
    violet: "text-violet-400 bg-violet-500/20",
    fuchsia: "text-fuchsia-400 bg-fuchsia-500/20",
    emerald: "text-emerald-400 bg-emerald-500/20",
    amber: "text-amber-400 bg-amber-500/20",
    rose: "text-rose-400 bg-rose-500/20",
  };

  const selectedGradient = gradient || "cyan";

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className={cn(
        "relative overflow-hidden rounded-2xl border p-6 h-[120px]",
        "bg-gradient-to-br",
        gradients[selectedGradient],
        "backdrop-blur-sm",
        className
      )}
    >
      <div className="flex items-start justify-between gap-3">
        <div className="space-y-2 min-w-0 flex-1">
          <p className="text-sm font-medium text-slate-600 dark:text-slate-400 flex items-center gap-1">
            {title}
            {tooltip && (
              <span
                ref={iconRef}
                className="inline-flex cursor-default"
                onMouseEnter={handleMouseEnter}
                onMouseLeave={handleMouseLeave}
              >
                <Info className="w-3 h-3 text-slate-500 hover:text-slate-300 transition-colors" />
              </span>
            )}
          </p>
          <p className="text-lg lg:text-2xl font-bold text-slate-900 dark:text-white tracking-tight">{value}</p>
          {subtitle && (
            <p className="text-xs text-slate-600 dark:text-slate-400 truncate">{subtitle}</p>
          )}
          {trendValue && (
            <div className={cn(
              "inline-flex items-center gap-1 text-xs font-medium px-2.5 py-1 rounded-full",
              isPositive && "bg-emerald-500/20 text-emerald-400",
              isNegative && "bg-rose-500/20 text-rose-400",
              !isPositive && !isNegative && "bg-slate-800 text-slate-600 dark:text-slate-400"
            )}>
              {isPositive && "↑"}
              {isNegative && "↓"}
              {trendValue}
            </div>
          )}
        </div>
        {Icon && (
          <div className={cn("p-3 rounded-xl flex-shrink-0", iconColors[selectedGradient])}>
            <Icon className="w-5 h-5" />
          </div>
        )}
      </div>

      {/* Glow effect */}
      <div className="absolute -bottom-8 -right-8 w-32 h-32 bg-gradient-to-br from-white/5 to-transparent rounded-full blur-2xl" />

      {/* Tooltip rendered via portal — escapes all stacking contexts */}
      {tooltip && tooltipVisible && createPortal(
        <div
          className="fixed z-[9999] w-56 rounded bg-slate-800 px-2 py-1.5 text-xs text-slate-200 shadow-lg pointer-events-none"
          style={{ top: tooltipPos.top, left: tooltipPos.left, transform: "translateY(-50%)" }}
        >
          {tooltip}
        </div>,
        document.body
      )}
    </motion.div>
  );
}
