import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { apiFetch, API_BASE_URL } from "../api/base44Client";
import { sortEntries } from "./useWatchlistData";

const FADE_OUT_DURATION_MS = 200;
const NAVIGATE_DELAY_MS = 220;

function buildWatchlistPrefillState(entry) {
  return {
    watchlist_prefill: {
      id: entry.id,
      ticker: entry.ticker,
      market: entry.market,
      entry_price: entry.target_entry_price != null ? String(entry.target_entry_price) : "",
      stop_price: entry.initial_stop_price != null ? String(entry.initial_stop_price) : "",
    },
  };
}

async function keepWatchlistEntry(entry, onUpdated) {
  try {
    const res = await apiFetch(`${API_BASE_URL}/watchlist/${entry.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ added_at: true }),
    });
    if (!res.ok) throw new Error();
    const json = await res.json();
    onUpdated(json.data);
    toast.success(`${entry.ticker} kept on watchlist.`);
  } catch {
    toast.error(`Failed to keep ${entry.ticker}. Please try again.`);
  }
}

export function useWatchlistModal(setEntries) {
  const navigate = useNavigate();
  const [modal, setModal] = useState(null);
  const [removing, setRemoving] = useState({});

  const fadeOutAndRemove = (id) => {
    setRemoving((prev) => ({ ...prev, [id]: true }));
    setTimeout(() => {
      setEntries((prev) => prev.filter((e) => e.id !== id));
      setRemoving((prev) => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
    }, FADE_OUT_DURATION_MS);
  };

  const handleAdded = (entry) => {
    setEntries((prev) => sortEntries([...prev, entry]));
    setModal(null);
  };

  const handleUpdated = (entry) => {
    setEntries((prev) =>
      sortEntries(prev.map((e) => (e.id === entry.id ? entry : e)))
    );
    setModal(null);
  };

  const handleDeleted = (id) => {
    setModal(null);
    fadeOutAndRemove(id);
  };

  const handleAddToPosition = (entry) => {
    fadeOutAndRemove(entry.id);
    setTimeout(() => {
      navigate("/TradeEntry", { state: buildWatchlistPrefillState(entry) });
    }, NAVIGATE_DELAY_MS);
  };

  const handleKeep = (entry) => keepWatchlistEntry(entry, handleUpdated);

  return { modal, setModal, removing, handleAdded, handleUpdated, handleDeleted, handleAddToPosition, handleKeep };
}
